```const Component: FC = () =&gt; {
  const [version, setVersion] = useState&lt;number | undefined&gt;(undefined);
  const [speakers, setSpeakers] = useState&lt;Array&lt;Speaker&gt; | undefined&gt;(
    undefined,
  );

  useEffect(() =&gt; {
    VoicevoxService.getVersion().then((value) =&gt; {
      setVersion(value);
    });
  }, []);

  useEffect(() =&gt; {
    VoicevoxService.getSpeakers().then((value) =&gt; {
      setSpeakers(value);
    });
  }, []);

  if (version == null || speakers == null) {
    return &lt;Loading /&gt;;
  }

  return (
    &lt;&gt;
      &lt;div&gt;{version}&lt;/div&gt;
      &lt;div&gt;
        {speakers.map((speaker) =&gt; {
          return (
            &lt;Picker.Item label={speaker.name} value={speaker.speakerUuid} /&gt;
          );
        })}
      &lt;/div&gt;
    &lt;/&gt;
  );
};```
大雑把にこんな感じと思います

